SELECT status, cost_bucket, cost_count, unique_carriers FROM (SELECT status, CASE WHEN cost >= 98 THEN 'high' WHEN cost >= 37 THEN 'mid' ELSE 'low' END AS cost_bucket, COUNT(cost) AS cost_count, COUNT(DISTINCT cost) AS unique_carriers FROM shipments GROUP BY status, CASE WHEN cost >= 98 THEN 'high' WHEN cost >= 37 THEN 'mid' ELSE 'low' END) AS s WHERE cost_count >= 3 ORDER BY cost_bucket ASC, cost_count ASC;
